@Test
public void practice_pruneFullSubtreesSize3_basicCase() {
    BinarySearchTree<String> bst = new BinarySearchTree<>();
    bst.insert("romeo");
    bst.insert("echo");
    bst.insert("tango");
    bst.pruneFullSubtreesSize3();
    assertEquals("[]", bst.toString());
    points += 3;
}

@Test
public void practice_countLeftNodesAtDepth_threeNodeTree() {
    BinarySearchTree<String> bst = new BinarySearchTree<>();
    bst.insert("november");
    bst.insert("foxtrot");
    bst.insert("tango");
    assertEquals(0, bst.countLeftNodesAtDepth(0));
    assertEquals(1, bst.countLeftNodesAtDepth(1));
    points += 1;
}

@Test
public void practice_shortestWordAlongPath_singleAndTwoNodes() {
    BinarySearchTree<String> bst = new BinarySearchTree<>();
    bst.insert("romeo");
    assertEquals("romeo", bst.shortestWordAlongPath("romeo"));
    bst.insert("echo");
    assertEquals("echo", bst.shortestWordAlongPath("echo"));
    assertEquals("romeo", bst.shortestWordAlongPath("romeo"));
    points += 1;
}

@Test
public void practice_removeMin_threeNodeTree() {
    BinarySearchTree<Integer> bst = new BinarySearchTree<>();
    bst.insert(10);
    bst.insert(5);
    bst.insert(15);
    assertEquals(5, (int) bst.removeMin());
    assertEquals("[10, 15]", bst.toString());
    points += 4;
}

@Test
public void practice_getPreOrderList_rootFirst() {
    BinarySearchTree<Integer> bst = new BinarySearchTree<>();
    bst.insert(10);
    bst.insert(5);
    bst.insert(15);
    ArrayList<Integer> list = bst.getPreOrderList();
    assertEquals(Integer.valueOf(10), list.get(0));
    assertEquals(Integer.valueOf(5), list.get(1));
    points += 1;
}
